{

    internal InnerOAuth2CredentialProviderSelfManagedLatticeResourceFactory SelfManagedLatticeResourceFactory { get; set; }

    internal InnerOAuth2CredentialProviderManagedVpcResourceFactory ManagedVpcResourceFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.PrivateEndpoint Create()
    {
        var privateEndpointResult = CreatePrivateEndpoint();
        factoryAction?.Invoke(privateEndpointResult);

        return privateEndpointResult;
    }

    private Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.PrivateEndpoint CreatePrivateEndpoint()
    {
        var privateEndpointResult = new Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.PrivateEndpoint();

        return privateEndpointResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.OAuth2CredentialProviderTypes.PrivateEndpoint result)
    {
        base.CreateChildren(result);

        result.SelfManagedLatticeResource ??= SelfManagedLatticeResourceFactory?.Build();
        result.ManagedVpcResource ??= ManagedVpcResourceFactory?.Build();
    }

} // End Of Class

